import React, { useCallback, useRef, useState } from 'react';
import { LiveboardEmbed } from '@thoughtspot/visual-embed-sdk/react';
import { THOUGHTSPOT_LIVEBOARD_ID, TOP_HEADER_PX } from '../config/thoughtspot';
import { useTier } from '../config/TierContext';
import { formatThoughtSpotEmbedError } from '../utils/thoughtspotErrors';

const BST_BLUE = '#1D3FA8';
const EMBED_MIN_H = `calc(100vh - ${TOP_HEADER_PX}px - 200px)`;

const VIEW_CHIPS = [
  { id: 'overview',    label: 'Overview',              tabId: '4cae1a0e-1887-4ffa-8058-891010ca0701' },
  { id: 'performance', label: 'Performance & Ranking', tabId: 'b05e15ee-aff3-4609-ae4c-46db06b28ac6' },
  { id: 'time',        label: 'Time Development',      tabId: 'c19dfa82-ba9d-4136-9317-eb941558f081' },
  { id: 'quality',     label: 'Quality & Failures',    tabId: 'a4164f3d-9f06-4aa3-9725-3e179efc474f' },
  { id: 'geography',   label: 'Geography & Customers', tabId: '8701338d-ab38-428e-8752-0c27e3462b3e' },
];

export default function DashboardHome() {
  const { hiddenActions, disabledActions } = useTier();
  const [selectedView, setSelectedView] = useState('overview');
  const selected = VIEW_CHIPS.find(v => v.id === selectedView)!;
  const embedRef = useRef<any>(null);

  // After load, call the SDK's own navigateToLiveboard to switch to the correct tab
  const onLoad = useCallback(() => {
    const chip = VIEW_CHIPS.find(v => v.id === selectedView)!;
    embedRef.current?.navigateToLiveboard(THOUGHTSPOT_LIVEBOARD_ID, undefined, chip.tabId);
  }, [selectedView]);

  const onError = useCallback((err: { data?: { errorMessage?: string }; message?: string }) => {
    console.error('[ThoughtSpot Liveboard]', formatThoughtSpotEmbedError(err), err);
  }, []);

  return (
    <div style={{ backgroundColor: BST_BLUE, minHeight: `calc(100vh - ${TOP_HEADER_PX}px)` }}>

      {/* Blue header */}
      <div style={{ padding: '1.75rem 2.5rem 1rem' }}>
        <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: '0.1em', textTransform: 'uppercase', color: 'rgba(255,255,255,0.55)', marginBottom: 6 }}>
          BST Media
        </div>
        <h1 style={{ fontSize: 26, fontWeight: 800, color: '#ffffff', margin: '0 0 1rem' }}>Logi Liveboard</h1>

        {/* View switcher pills */}
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
          {VIEW_CHIPS.map(chip => {
            const isActive = chip.id === selectedView;
            return (
              <button
                key={chip.id}
                type="button"
                onClick={() => setSelectedView(chip.id)}
                style={{
                  padding: '7px 16px',
                  borderRadius: 20,
                  border: `1px solid ${isActive ? '#ffffff' : 'rgba(255,255,255,0.35)'}`,
                  background: isActive ? '#ffffff' : 'rgba(255,255,255,0.1)',
                  color: isActive ? BST_BLUE : 'rgba(255,255,255,0.85)',
                  fontSize: 13,
                  fontWeight: isActive ? 700 : 500,
                  cursor: 'pointer',
                  transition: 'all 0.15s ease',
                  whiteSpace: 'nowrap',
                }}
              >
                {chip.label}
              </button>
            );
          })}
        </div>
      </div>

      {/* Embed card */}
      <div style={{ padding: '0 2.5rem 2rem' }}>
        <div style={{ backgroundColor: '#ffffff', borderRadius: 12, overflow: 'visible', minHeight: EMBED_MIN_H }}>
          <LiveboardEmbed
            ref={embedRef}
            key={selectedView}
            liveboardId={THOUGHTSPOT_LIVEBOARD_ID}
            activeTabId={selected.tabId}
            fullHeight
            isLiveboardStylingAndGroupingEnabled
            hiddenActions={hiddenActions}
            disabledActions={disabledActions}
            onLoad={onLoad}
            onError={onError}
            style={{ width: '100%', minHeight: EMBED_MIN_H, display: 'block', border: 'none' }}
          />
        </div>
      </div>
    </div>
  );
}
